def check_imponibile_positivo(posizioni):
    if not posizioni:
        return True

    for pos in posizioni:
        if pos and 'imponibile' in pos:
            if pos['imponibile'] is not None and pos['imponibile'] <= 0:
                return False
    return True
check_imponibile_positivo_udf = udf(check_imponibile_positivo, BooleanType())

dfCheckImponibile = fatture_df.withColumn("impPositivo", check_imponibile_positivo_udf(col("posizioni")))
